  "That email and password don’t match. Try again, or use the reset link.": "이메일과 비밀번호가 일치하지 않습니다. 다시 시도하거나 재설정 링크를 사용하세요.",
  "Please confirm your email first. Tap the link we sent you, then sign in.": "먼저 이메일을 확인하세요. 보내 드린 링크를 탭한 뒤 로그인하세요.",
