  "Tap Follow on a ride page to hear when that leader posts a new public ride.": "라이드 페이지에서 팔로우를 탭하면 해당 리더가 새 공개 라이드를 올릴 때 알려 드립니다.",
  "No Groups Yet": "아직 그룹이 없습니다",
  "Make one for the friends you ride with most weekends. Add people you’ve ridden with, or send the group link to anyone else.": "주말마다 함께 타는 친구들을 위한 그룹을 만드세요. 함께 탄 사람을 추가하거나 다른 사람에게 그룹 링크를 보내세요.",
