  "Your Email Is Confirmed": "이메일이 확인되었습니다",
  "This link opened somewhere other than where you signed up, so sign in once more with your email and password.": "가입한 곳과 다른 곳에서 링크가 열렸습니다. 이메일과 비밀번호로 한 번 더 로그인하세요.",
  "That Link Didn’t Work": "링크가 작동하지 않았습니다",
  "Back to Sign In": "로그인으로 돌아가기",
  "Sign in to earn badges for the rides you lead, join and finish.": "로그인하면 이끈 라이드, 참여한 라이드, 완주한 라이드로 배지를 받을 수 있습니다.",
  "Badges start working with the next server update.": "배지는 다음 서버 업데이트부터 작동합니다.",
  "Try Again": "다시 시도",
  "A ride counts once it ends, for riders whose own location track covers at least half a mile. Leading, tail gunning and group rides need at least two riders with a track. Badges are earned on the server from what you really ride, so they can’t be added by hand. OnMyLead Founder and Brand Ambassador are the exceptions: OnMyLead gives them, and they don’t count toward your rank.": "라이드는 종료 후, 본인의 위치 기록이 최소 0.5마일 이상인 라이더에게 집계됩니다. 리드, 후미, 그룹 라이드는 기록이 있는 라이더가 최소 2명 필요합니다. 배지는 실제로 탄 기록을 바탕으로 서버에서 부여되므로 직접 추가할 수 없습니다. OnMyLead Founder와 Brand Ambassador는 예외로, OnMyLead가 수여하며 등급에 포함되지 않습니다.",
  "Your Rank": "내 등급",
  "New": "신규",
  "{what}. Riders see it beside your name.": "{what}. 라이더들이 이름 옆에서 볼 수 있습니다.",
  "Keep Current": "현재 설정 유지",
  "Saved, but your current share didn’t switch over. Open Ride Mode to restart sharing with the new setting.": "저장했지만 현재 공유는 전환되지 않았습니다. 라이드 모드를 열어 새 설정으로 공유를 다시 시작하세요.",
  "How often this device tells your group where you are while you share your location. Fewer updates use less battery.": "위치를 공유하는 동안 이 기기가 그룹에 내 위치를 알리는 빈도입니다. 업데이트가 적을수록 배터리를 덜 씁니다.",
  "Your Group Sees You Less Often": "그룹에 덜 자주 표시됩니다",
  "Your dot can trail up to {heartbeatSec} seconds behind you, so you’re harder to follow and to find if you stop.": "내 점이 최대 {heartbeatSec}초 늦게 표시될 수 있어 따라오기 어렵고, 멈췄을 때 찾기도 어렵습니다.",
  "Switch Back to Best Accuracy": "최고 정확도로 되돌리기",
  "This setting is for this device only. Need Help, EMERGENCY and your other taps still send right away on every setting. Other riders aren’t told which one you picked.": "이 설정은 이 기기에만 적용됩니다. 도움 필요, 긴급 등 다른 탭은 어떤 설정에서든 즉시 전송됩니다. 다른 라이더에게는 무엇을 골랐는지 알려지지 않습니다.",
  "Recommended": "추천",
  "You don’t see their messages in ride chat or group chat, or get chat notifications from them. They aren’t told. Need Help and EMERGENCY alerts from a ride you’re on always come through.": "라이드 채팅이나 그룹 채팅에서 그 사람의 메시지가 보이지 않고 채팅 알림도 받지 않습니다. 상대에게는 알려지지 않습니다. 참여 중인 라이드의 도움 필요와 긴급 알림은 항상 전달됩니다.",
  "Loading…": "불러오는 중…",
  "Nobody Blocked": "차단한 사람이 없습니다",
  "To block a rider, tap them in a ride’s Going list, or long press one of their messages.": "라이더를 차단하려면 라이드의 참가자 목록에서 탭하거나 메시지를 길게 누르세요.",
  "Unblock": "차단 해제",
  "Your pictures couldn’t be opened. Allow OnMyLead to see your photos in Settings, or send the message without one.": "사진을 열 수 없습니다. 설정에서 OnMyLead의 사진 접근을 허용하거나 사진 없이 메시지를 보내세요.",
  "Message Sent | OnMyLead": "메시지 전송됨 | OnMyLead",
