  "When shared, leave off the first and last {v}, for a trail that starts at your house or camp. Off shares the whole trail.": "공유할 때 처음과 마지막 {v}를 제외합니다. 집이나 캠프에서 시작하는 트레일용입니다. 끄면 트레일 전체를 공유합니다.",
