  "Name ledges, crossings and viewpoints with Mark a Spot while drawing or recording in Map Mode. Tap one here to rename or remove it.": "지도 모드에서 그리거나 기록하는 동안 지점 표시로 턱, 도강, 전망대에 이름을 붙이세요. 여기서 탭하면 이름을 바꾸거나 삭제할 수 있습니다.",
