  "No Trails Yet": "아직 트레일이 없습니다",
  "In Map Mode, tap Record and ride, or Draw to map a custom trail. Your trails are private until you share them, and they show on every device you sign in on. A rider trail you save shows here too.": "지도 모드에서 기록을 탭하고 달리거나, 그리기로 사용자 트레일을 만드세요. 트레일은 공유하기 전까지 비공개이며, 로그인한 모든 기기에 표시됩니다. 저장한 라이더 트레일도 여기에 표시됩니다.",
  "Notifications Come to the iPhone App": "알림은 iPhone 앱으로 옵니다",
  "Your choices here apply on your phone too.": "여기서 선택한 내용은 휴대폰에도 적용됩니다.",
  "Notifications Are Off for OnMyLead": "OnMyLead 알림이 꺼져 있습니다",
  "Your phone is blocking them, so nothing below can reach you. Turn on Allow Notifications for OnMyLead.": "휴대폰이 알림을 차단하고 있어 아래 항목이 전달되지 않습니다. OnMyLead의 알림 허용을 켜세요.",
  "Let OnMyLead Send Notifications": "OnMyLead 알림 허용",
  "Turn On Notifications": "알림 켜기",
  "So you hear when someone in your group needs help, even with the phone in your pocket.": "휴대폰이 주머니에 있어도 그룹의 누군가가 도움이 필요할 때 알 수 있습니다.",
  "These settings start working with the next server update. Until then, ride chat still pops up while the app is open.": "이 설정은 다음 서버 업데이트부터 작동합니다. 그전까지는 앱이 열려 있을 때 라이드 채팅이 표시됩니다.",
  "Help and EMERGENCY alerts are always on, even in quiet hours.": "도움 및 긴급 알림은 방해 금지 시간에도 항상 켜져 있습니다.",
  "SOS": "SOS",
  "Help and EMERGENCY": "도움 및 긴급",
  "When someone in your group taps Need help or EMERGENCY. Always on, even in quiet hours.": "그룹의 누군가가 도움 필요 또는 긴급을 탭할 때. 방해 금지 시간에도 항상 켜져 있습니다.",
  "Email When a Ride Is Cancelled": "라이드 취소 시 이메일",
  "An email if a ride you joined is cancelled or removed, as well as the notification.": "참여한 라이드가 취소되거나 삭제되면 알림과 함께 이메일도 보냅니다.",
  "Email Me Too": "이메일로도 받기",
