  "Windrock Park": "Windrock Park",
  "Riders see your name and roughly how far away you are, never where you are. It turns off on its own at the end you pick, or after {IDLE_HOURS} hours without opening OnMyLead.{v}": "라이더는 내 이름과 대략적인 거리만 볼 수 있고, 위치는 절대 볼 수 없습니다. 선택한 시간에 자동으로 꺼지며, OnMyLead를 {IDLE_HOURS}시간 동안 열지 않아도 꺼집니다.{v}",
  "Your browser will ask for your location.": "브라우저가 위치를 요청합니다.",
  "Go Out Riding": "라이딩 시작",
