  "Draw the trail on the map or import a GPX file. Riders see it in Ride Mode with everyone placed along it.": "지도에 트레일을 그리거나 GPX 파일을 가져오세요. 라이더들은 라이드 모드에서 경로 위에 표시된 모두의 위치와 함께 봅니다.",
