  "Chat": "채팅",
  "Pick who you want to report for harassment, threats or anything else that breaks the rider rules. It goes to the OnMyLead team. They aren’t told who reported them. If anyone is in danger, call 911.": "괴롭힘, 협박 또는 라이더 규칙을 어긴 사람을 골라 신고하세요. 신고는 OnMyLead 팀에 전달됩니다. 신고자는 상대에게 알려지지 않습니다. 누군가 위험하다면 911에 전화하세요.",
  "Search": "검색",
  "Rider name": "라이더 이름",
  "Riders you’ve messaged, ridden with, added as friends or blocked show here. You can also report a rider from their message, a ride’s Going list or Out Riding.": "메시지를 주고받았거나, 함께 라이딩했거나, 친구로 추가했거나, 차단한 라이더가 여기에 표시됩니다. 메시지, 라이드의 참가자 목록 또는 라이딩 중에서도 라이더를 신고할 수 있습니다.",
