  "OnMyLead can’t see your location, so your group won’t see you move. Turn on location for OnMyLead in Settings to keep sharing.": "OnMyLead가 위치를 볼 수 없어 그룹이 내 이동을 볼 수 없습니다. 계속 공유하려면 설정에서 OnMyLead의 위치를 켜세요.",
