  "Resolved, I’m OK": "해결됨, 괜찮아요",
  "Brings back messages, status buttons and the ride. You can also swipe the bar up": "메시지, 상태 버튼, 라이드를 다시 보여줍니다. 바를 위로 밀어도 됩니다",
  "Send status EMERGENCY": "긴급 상태 보내기",
