  "Buttons ▲": "버튼 ▲",
  "Share Your Location with This Ride?": "이 라이드와 위치를 공유할까요?",
  "Only riders on this ride will see you. Sharing always stops when the ride ends or you leave it.": "이 라이드의 라이더만 나를 볼 수 있습니다. 라이드가 끝나거나 나가면 공유는 항상 멈춥니다.",
  "Emergency": "긴급",
  "This alerts everyone on the ride with your location. It does not contact emergency services. Call 911 if anyone is hurt.": "라이드의 모두에게 내 위치와 함께 알림을 보냅니다. 긴급 서비스에 연락하지는 않습니다. 다친 사람이 있으면 911에 전화하세요.",
  "Alert My Group": "그룹에 알리기",
