  "Set the meeting point: search a place, use your location or paste coordinates like \"38.57, -109.55\".": "모임 장소를 정하세요: 장소를 검색하거나, 내 위치를 사용하거나, \"38.57, -109.55\" 같은 좌표를 붙여넣으세요.",
  "Pick Mapped or Freeride under The Route.": "경로에서 지정 경로 또는 프리라이드를 고르세요.",
  "Plan it here on the big screen. The ride, its route and its stops show up in the OnMyLead app on your iPhone as soon as you save.": "큰 화면에서 계획하세요. 저장하면 라이드, 경로, 정차 지점이 iPhone의 OnMyLead 앱에 바로 나타납니다.",
  "Riding {copiedFrom} Again": "{copiedFrom} 다시 라이딩",
  "Riding {fromTrail}": "{fromTrail} 라이딩",
  "The trail is the route, and its start is the meeting point. Change anything, pick the day and create it.": "트레일이 경로가 되고, 그 시작점이 모임 장소가 됩니다. 원하는 대로 바꾸고 날짜를 고른 뒤 만드세요.",
  "{v} Width Limit": "{v} 폭 제한",
  "For Your Event": "이벤트용",
  "Once it’s created, this ride shows under the event’s Group Rides.": "만들고 나면 이 라이드는 이벤트의 그룹 라이드에 표시됩니다.",
