  "Sharing Now, {v}": "지금 공유 중, {v}",
  "This keeps going, even for days, until you tap Stop Sharing.": "공유 중지를 탭할 때까지 며칠이 지나도 계속됩니다.",
  "Includes a family link": "가족 링크 포함",
  "Who Can See You": "나를 볼 수 있는 사람",
  "People you’ve ridden with show up here. You can still share a family link.": "함께 라이딩한 사람이 여기에 표시됩니다. 가족 링크는 여전히 공유할 수 있습니다.",
  "Family Link": "가족 링크",
  "A read-only web link for someone without the app. It stops working when sharing ends.": "앱이 없는 사람을 위한 읽기 전용 웹 링크입니다. 공유가 끝나면 작동하지 않습니다.",
  "For How Long": "기간",
  "Share Until You Turn It Off?": "끌 때까지 공유할까요?",
  "There is no time limit. Your location keeps sharing, even for days, until you come back here and tap Stop Sharing.": "시간 제한이 없습니다. 여기로 돌아와 공유 중지를 탭할 때까지 며칠이 지나도 위치가 계속 공유됩니다.",
  "you@example.com": "you@example.com",
  "Nothing here yet. When your friends ride, earn badges, share trails or post, it shows up here for you to like and comment on.": "아직 아무것도 없습니다. 친구가 라이딩하거나, 배지를 얻거나, 트레일을 공유하거나, 글을 올리면 여기에 표시되어 좋아요와 댓글을 남길 수 있습니다.",
  "On Free you can see everything and like it. Pro lets you post, comment and share to Facebook, Instagram and X.": "Free에서는 모든 것을 보고 좋아요를 누를 수 있습니다. Pro에서는 글 쓰기, 댓글, Facebook·Instagram·X 공유가 가능합니다.",
  "Your Friends": "내 친구",
  "View Your Profile": "내 프로필 보기",
  "Activity": "활동",
  "My Posts": "내 게시물",
  "Delete This Comment?": "이 댓글을 삭제할까요?",
  "Delete comment": "댓글 삭제",
  "Report": "신고",
  "Comment": "댓글",
  "Post comment": "댓글 올리기",
  "{v} left": "{v} 남음",
  "Commenting is part of OnMyLead Pro. Reading and liking stay free.": "댓글은 OnMyLead Pro 기능입니다. 읽기와 좋아요는 계속 무료입니다.",
  "Posting is part of OnMyLead Pro.": "글 쓰기는 OnMyLead Pro 기능입니다.",
  "How was the ride? Trail conditions, the crew, the view…": "라이드는 어땠나요? 트레일 상태, 함께한 사람들, 경치…",
  "Your post": "내 게시물",
  "{v} characters left": "{v}자 남음",
  "The photo for your post": "게시물 사진",
  "Take Photo": "사진 찍기",
  "Add Photo": "사진 추가",
  "Shows on your profile and in the feeds of the riders your Who Sees Your Activity setting allows. Your location is never added. Keep it friendly: riders can report posts, and the OnMyLead team removes ones that break the rules.": "내 프로필과, 내 활동 공개 범위 설정이 허용한 라이더의 피드에 표시됩니다. 위치는 절대 추가되지 않습니다. 친절하게 써 주세요: 라이더가 게시물을 신고할 수 있고, OnMyLead 팀이 규칙을 어긴 게시물을 삭제합니다.",
  "Edit Name and Picture": "이름과 사진 편집",
  "You and {name} can’t see each other’s activity. Unblock them from You, Blocked Riders.": "나와 {name}님은 서로의 활동을 볼 수 없습니다. 나 > 차단한 라이더에서 차단을 해제하세요.",
  "{name} shares rides, badges and posts with their friends. Become friends to see them here.": "{name}님은 친구에게 라이드, 배지, 게시물을 공유합니다. 친구가 되면 여기서 볼 수 있습니다.",
  "See how your dish is doing, keep your plan details handy, and work out how long your batteries will run it.": "안테나 상태를 확인하고, 요금제 정보를 가까이 두고, 배터리로 얼마나 쓸 수 있는지 계산하세요.",
  "Your Dish": "내 안테나",
  "Reading your dish only works in the OnMyLead phone app. Your dish talks to devices on its own Wi-Fi at {DISH_HOST}, and web browsers block a secure web page from reaching it.": "안테나 읽기는 OnMyLead 휴대폰 앱에서만 됩니다. 안테나는 자체 Wi-Fi의 {DISH_HOST}에서 기기와 통신하는데, 웹 브라우저는 보안 웹 페이지가 여기에 접근하는 것을 막습니다.",
  "You can still save your plan and use the power calculator below.": "요금제 저장과 아래의 전력 계산기는 계속 쓸 수 있습니다.",
  "Live": "실시간",
  "Last read {v} ago": "{v} 전에 마지막으로 읽음",
  "Join your Starlink Wi-Fi, then tap Connect. This page then stays live while it is open.": "Starlink Wi-Fi에 연결한 뒤 연결을 탭하세요. 이 페이지가 열려 있는 동안 실시간으로 유지됩니다.",
  "Can’t Reach Your Dish": "안테나에 연결할 수 없습니다",
