  "Alerts": "알림",
  "No alerts.": "알림 없음.",
  "This uses your dish’s built-in local connection, which SpaceX doesn’t officially support. A Starlink update can break it; everything else on this page keeps working.": "안테나의 내장 로컬 연결을 사용하며, SpaceX가 공식 지원하지 않는 방식입니다. Starlink 업데이트로 작동하지 않을 수 있지만 이 페이지의 나머지 기능은 계속 작동합니다.",
  "Last {v} Min": "최근 {v}분",
