  "Reward Applied": "보상 적용됨",
  "Your next Google Play bill was pushed back 6 months. Thanks for spreading the word.": "다음 Google Play 청구가 6개월 미뤄졌습니다. 알려주셔서 감사합니다.",
  "Reward Used": "보상 사용됨",
