  "Leaderboard. See where you rank in your state, your country and everywhere": "순위표. 주, 국가, 전체에서 내 순위 보기",
  "No country matches “{v}”.": "“{v}”와(과) 일치하는 국가가 없습니다.",
  "No tilt tile, readings or tilt warnings. Crash Alert still works.": "기울기 타일, 측정값, 기울기 경고가 없습니다. 사고 알림은 계속 작동합니다.",
  "Pick the state or country you ride from to be on its leaderboard. Riders see it beside your name there, and nowhere else. It’s optional, and it never shares where you are.": "라이딩하는 주나 국가를 고르면 그곳의 순위표에 오릅니다. 라이더는 거기서만 내 이름 옆에 표시된 것을 봅니다. 선택 사항이며 내 위치는 절대 공유하지 않습니다.",
  "Pick where you ride from to be on country and state boards.": "라이딩하는 지역을 고르면 국가 및 주 순위표에 오릅니다.",
  "Place your phone where it will be mounted, with the vehicle on flat and level ground, then press {button} to calibrate it.": "차량을 평평하고 수평인 곳에 두고 휴대폰을 장착할 위치에 놓은 뒤 {button}을(를) 눌러 보정하세요.",
  "Remove My Area": "내 지역 삭제",
  "Riders are ranked by the badge levels they earned by riding, the same count as their rank. Ties go to more Gold, then more Silver, then whoever got there first. Brand Ambassador and OnMyLead Founder don’t count. Only your name, picture, badges and the state or country you picked show here, never where you are.": "라이더는 라이딩으로 얻은 배지 레벨(랭크와 같은 수)로 순위가 정해집니다. 동점이면 골드가 많은 사람, 그다음 실버가 많은 사람, 그다음 먼저 달성한 사람이 앞섭니다. Brand Ambassador와 OnMyLead Founder는 포함되지 않습니다. 여기에는 이름, 사진, 배지, 고른 주나 국가만 표시되며 내 위치는 절대 표시되지 않습니다.",
  "Roll and pitch on this screen and in Map Mode and Ride Mode.": "이 화면과 지도 모드, 라이드 모드에서 롤과 피치를 표시합니다.",
  "Saving 3D Terrain, {v}%": "3D 지형 저장 중, {v}%",
  "Search Countries": "국가 검색",
  "See where you rank in your state, your country and everywhere": "주, 국가, 전체에서 내 순위 보기",
  "Settings and trails on all your devices": "모든 기기에서 설정과 트레일",
  "Settings and trails on all your devices. Synced {when}": "모든 기기에서 설정과 트레일. {when} 동기화됨",
  "Show Me on the Leaderboard": "순위표에 나 표시",
  "Sign in to see where you rank among riders in your state, your country and everywhere.": "로그인하면 주, 국가, 전체 라이더 중 내 순위를 볼 수 있습니다.",
  "Somewhere else? Type its name.": "다른 곳인가요? 이름을 입력하세요.",
  "Syncing now…": "동기화 중…",
