  "The tilt meter is off until you calibrate it. Place your phone where it will be mounted, with the vehicle on flat and level ground, then press Calibrate.": "기울기 미터는 보정하기 전까지 꺼져 있습니다. 차량을 평평하고 수평인 곳에 두고 휴대폰을 장착할 위치에 놓은 뒤 보정을 누르세요.",
