  "No Service. Sharing With {n} Nearby Phones Over Bluetooth.": "서비스 없음. 블루투스로 근처 휴대폰 {n}대와 공유 중.",
  "No Service. Sharing With {n} Nearby Phone Over Bluetooth (Your Spot Stays Private Until You Share).": "서비스 없음. 블루투스로 근처 휴대폰 {n}대와 공유 중 (공유하기 전까지 내 위치는 비공개).",
  "No Service. Sharing With {n} Nearby Phones Over Bluetooth (Your Spot Stays Private Until You Share).": "서비스 없음. 블루투스로 근처 휴대폰 {n}대와 공유 중 (공유하기 전까지 내 위치는 비공개).",
