  "Your browser and a short log of what the page just did go with your message, to help us fix it. Never your location or anything you typed.": "문제 해결을 위해 브라우저 정보와 페이지가 방금 한 작업의 짧은 로그가 메시지와 함께 전송됩니다. 위치나 입력한 내용은 절대 포함되지 않습니다.",
  "Your phone model, app version and a short log of what the app just did go with your message, to help us fix it. Never your location or anything you typed.": "문제 해결을 위해 휴대폰 모델, 앱 버전, 앱이 방금 한 작업의 짧은 로그가 메시지와 함께 전송됩니다. 위치나 입력한 내용은 절대 포함되지 않습니다.",
  "We couldn’t find that event.": "해당 이벤트를 찾을 수 없습니다.",
