  "{v} at {location_name}. Agenda, group rides and who’s going on OnMyLead.": "{v}, {location_name}. 일정, 그룹 라이드, 참가자는 OnMyLead에서.",
  "Pick a Ride Manager": "라이드 담당자 고르기",
  "Add a Co-Host": "공동 주최자 추가",
  "They become a Co-Organizer of {name}: they can approve riders, set roles and run the ride. If they aren’t on it yet, they get an invite first.": "{name}의 공동 주최자가 됩니다. 라이더 승인, 역할 지정, 라이드 진행이 가능합니다. 아직 참여하지 않았다면 먼저 초대를 받습니다.",
