  "{drop} the map where the group will stop, or Search for the place. Stops are numbered in the order you add them.": "그룹이 멈출 곳에서 지도를 {drop} 장소를 검색하세요. 정차 지점은 추가한 순서대로 번호가 붙습니다.",
  "{drop} the map to drop a waypoint, or Search for a place. You choose whether the whole ride sees it.": "지도를 {drop} 웨이포인트를 놓거나 장소를 검색하세요. 라이드 전체에 보일지 직접 정합니다.",
  "{drop} the map to drop a waypoint, or Search for a place. Yours are only for you.": "지도를 {drop} 웨이포인트를 놓거나 장소를 검색하세요. 내 것은 나만 봅니다.",
