  "The details, meeting point and route are filled in. Pick the day, check the times and create it.": "세부 정보, 집결지, 경로가 채워졌습니다. 날짜를 고르고 시간을 확인한 뒤 만드세요.",
  "The details and meeting point are filled in. Pick the day, check the times and create it.": "세부 정보와 집결지가 채워졌습니다. 날짜를 고르고 시간을 확인한 뒤 만드세요.",
  "Listed in {name}.": "{name}에 등록됨.",
