  "Join your Starlink Wi-Fi and allow OnMyLead to use your local network (Settings › OnMyLead). We keep trying every 10 seconds.": "Starlink Wi-Fi에 연결하고 OnMyLead의 로컬 네트워크 사용을 허용하세요(설정 › OnMyLead). 10초마다 다시 시도합니다.",
