  "Something not working, or a question about OnMyLead? Send us a message with the Contact Us form below, or email {v}, and a real person at {v2} will answer, usually within a day.": "뭔가 안 되거나 OnMyLead에 관해 궁금한 점이 있나요? 아래 문의하기 양식으로 메시지를 보내거나 {v}로 이메일을 보내면 {v2}의 실제 담당자가 보통 하루 안에 답합니다.",
  "Ask the organizer for the ride code or link, or scan their QR code with your {v} camera. Then tap Join a Ride on the Rides tab.": "주최자에게 라이드 코드나 링크를 받거나 {v} 카메라로 QR 코드를 스캔하세요. 그런 다음 라이드 탭에서 라이드 참가를 탭하세요.",
