  "Already have it? Open the ride right where you left off. New here? Get the app, then scan or open the link again.": "이미 앱이 있나요? 멈춘 곳에서 라이드를 바로 엽니다. 처음인가요? 앱을 받은 뒤 다시 스캔하거나 링크를 여세요.",
