  "Scan this with your phone’s camera to open the ride on your phone. Your group shares one live map and chat, and the leader’s route.": "휴대폰 카메라로 스캔하면 휴대폰에서 라이드가 열립니다. 그룹이 실시간 지도, 채팅, 리더의 경로를 함께 봅니다.",
