  "Only people you send this to can find it. They can scan the QR code, open the link or type the code.": "보낸 사람만 찾을 수 있습니다. QR 코드 스캔, 링크 열기, 코드 입력 중 하나로 참여합니다.",
  "Anyone can find it near them or in your state. Send it to friends too.": "근처나 같은 주의 누구나 찾을 수 있습니다. 친구에게도 보내세요.",
  "The old link, QR code and code stop working. Riders already on the ride stay on it.{v}": "이전 링크, QR 코드, 코드는 더 이상 작동하지 않습니다. 이미 참여한 라이더는 그대로 남습니다.{v}",
