  "Android shares what’s playing only with apps you allow under Notification Access. OnMyLead never reads your notifications.": "Android는 알림 접근을 허용한 앱에만 재생 중인 곡을 공유합니다. OnMyLead는 알림을 절대 읽지 않습니다.",
  "Lets OnMyLead show the Apple Music song. It stays on your phone.": "OnMyLead가 Apple Music 곡을 표시하게 합니다. 정보는 휴대폰에만 남습니다.",
